        paint_used, mask, groups = heapq.heappop(pq)

        if dp[mask][groups] < paint_used:
            continue

        for i in range(n):
            if mask & (1 << i):
                continue

            new_mask = mask | (1 << i)

            for j in range(1, m + 1):
                new_paint_used = paint_used + paint[i][j - 1]

                if colors[i] == 0 or colors[i] == j:
                    new_groups = groups

