                        new_groups += 1

                    if new_groups <= k and new_paint_used < dp[new_mask][new_groups]:
                        dp[new_mask][new_groups] = new_paint_used
                        heapq.heappush(pq, (new_paint_used, new_mask, new_groups))

    result = min(dp[(1 << n) - 1][k:])

